-      .lineWidth(width)
-      .moveTo(p1[0], p1[1] + r1)
-      .quadraticCurveTo(p1[0], p1[1], p1[0] + r1, p1[1])
-      .lineTo(p2[0] - r2, p2[1])
-      .quadraticCurveTo(p2[0], p2[1], p2[0], p2[1] + r2)
